    "giftRules": [],
    "affinityDialogue": {
      "0": [
        {
          "npc": "阵法之道，在于布局。",
          "player": "愿闻其详。"
        },
        {
          "npc": "（翻开书）有事？",
          "player": "想学阵法。"
        },
        {
          "npc": "你踩到我的阵纹了。",
          "player": "抱歉。"
        }
      ],
      "30": [
        {
          "npc": "你的步子，比上次稳了。",
          "player": "练过几回。"
        },
        {
          "npc": "布阵前先看地势，再看人。",
          "player": "记住了。"
        },
        {
          "npc": "（轻轻叹气）加雷斯又说我摆架子。",
          "player": "你们有矛盾？"
        }
      ],
      "60": [
        {
          "npc": "（合上书）我画的阵，救过人，也困过自己。",
          "player": "困过自己？"
        },
        {
          "npc": "七年前，我封了一座桥。",
          "player": "为什么？"
        },
        {
          "npc": "（沉默）……里面还有我的一位朋友。",
          "player": "……"
        },
        {
          "npc": "奥菲莉亚那孩子，比我干净。",
          "player": "她是你师妹？"
        }
      ],
      "90": [
        {
          "npc": "（把一册手抄阵谱推过来）拿去。",
          "player": "这太贵重了。"
        },
        {
          "npc": "别还我。还了就说明你没看懂。",
          "player": "……我收下了。"
        },
        {
          "npc": "以后布阵，记得给自己留一道退路。",
          "player": "好。"
        }
      ]
    },
