/* ---- 通用工具（运行时/战斗/编辑器共用） ---- */
function dcClone(o){ return o == null ? o : JSON.parse(JSON.stringify(o)); }
function dcEmptyEquipment(){
  const e = {};
  (typeof EQUIP_SLOTS !== 'undefined' ? EQUIP_SLOTS : ['mainHand','offHand','head','chest','legs','accessory','charm','feet'])
    .forEach(s => e[s] = null);
  return e;
}

function getCharacterTemplate(id){
  if(!id) return null;
  const base = String(id).split('#')[0];
  return CHARACTERS[base] || ENVIRONMENTS[id] || null;
}
/* 地图挂载实例：优先读 tile.actors 上的配置，旧模板字段只做兼容回退。 */
function findPlacementActor(charId, placementId){
  if(!placementId || typeof MAPS === 'undefined') return null;
  const tileId = String(placementId).split('::')[0] || '';
  for(const mapId in MAPS){
    const tile = (MAPS[mapId].tiles || []).find(t => t.id === tileId);
    if(!tile) continue;
    const list = Array.isArray(tile.actors) && tile.actors.length
      ? tile.actors
      : (typeof buildTileActors === 'function' ? buildTileActors(tile) : []);
    return list.find(a => (a.placementId || '') === placementId)
      || list.find(a => a.charId === String(charId || '').split('#')[0])
      || null;
  }
  return null;
}
function placementActorConfig(charId, placementId){
  const tpl = getCharacterTemplate(charId) || {};
  const actor = findPlacementActor(charId, placementId);
  const classes = Array.isArray(tpl.classes) ? tpl.classes : [];
  const services = (actor && actor.services) ? actor.services : {
    trainer: !!tpl.isTrainer,
    trader: !!tpl.isTrader || classes.indexOf('商人') >= 0,
    repairer: !!tpl.isRepairer || classes.indexOf('铁匠') >= 0,
    shopItems: Array.isArray(tpl.shopItems) ? tpl.shopItems.slice() : [],
    professions: Array.isArray(tpl.professions) ? tpl.professions.slice() : [],
    skillShop: Array.isArray(tpl.skillShop) ? tpl.skillShop.slice() : []
  };
  return {
    actor: actor,
    recruitMode: actor && actor.recruitMode
      ? actor.recruitMode
      : (tpl.isPet ? 'pet' : (tpl.canRecruit === false ? 'none' : 'companion')),
    respawn: actor && actor.respawn !== undefined
      ? !!actor.respawn
      : !!tpl.respawnAfterRecruit,
    returnTile: (actor && actor.returnTile) || tpl.homeTile || null,
    hidden: actor && actor.hidden !== undefined
      ? !!actor.hidden
      : !!tpl.isHidden,
    unique: actor && actor.unique !== undefined
      ? !!actor.unique
      : !tpl.allowMultipleMount,
    allowMultipleCopies: actor && actor.allowMultipleCopies !== undefined
      ? !!actor.allowMultipleCopies
      : !!tpl.allowMultipleCopies,
    services: services,
    level: actor ? (Number(actor.level) || null) : null,
    condition: actor ? (actor.condition || null) : null
  };
}
function effectiveCharacterForPlacement(charId, placementId){
  const tpl = getCharacterTemplate(charId);
  if(!tpl) return null;
  const cfg = placementActorConfig(charId, placementId);
  const out = Object.assign({}, tpl);
  out.isPet = cfg.recruitMode === 'pet';
  out.canRecruit = cfg.recruitMode !== 'none';
  out.respawnAfterRecruit = cfg.respawn;
  out.homeTile = cfg.returnTile;
  out.isHidden = cfg.hidden;
  out.allowMultipleMount = !cfg.unique;
  out.allowMultipleCopies = cfg.allowMultipleCopies;
  out.isTrainer = !!cfg.services.trainer;
  out.isTrader = !!cfg.services.trader;
  out.isRepairer = !!cfg.services.repairer;
  out.shopItems = Array.isArray(cfg.services.shopItems) ? cfg.services.shopItems.slice() : [];
  out.professions = Array.isArray(cfg.services.professions) ? cfg.services.professions.slice() : [];
  out.skillShop = Array.isArray(cfg.services.skillShop) ? cfg.services.skillShop.slice() : [];
  return out;
}
function getCharacter(id){
  if(!id) return null;
  if(typeof currentGame !== 'undefined' && currentGame){
    if(currentGame.characters && currentGame.characters[id]) return currentGame.characters[id];
    if(currentGame.npcs && currentGame.npcs[id]) return currentGame.npcs[id];
  }
  return getCharacterTemplate(id);
}
function isCharacterTemplate(id){
  return !!CHARACTERS[String(id || '').split('#')[0]];
}
function isDemonOrCult(char){
  const c = char || {};
  const tags = Array.isArray(c.factionTags) ? c.factionTags : [];
  return tags.includes('魔军') || tags.includes('邪教')
    || c.faction === '魔军' || c.faction === '邪教';
}
function isRecruitableCharacter(char){
  return !!char && !char.isPet && !char.deceased && char.canRecruit !== false && !isDemonOrCult(char);
}

/* 编辑器/调试只读视图：所有角色模板统一归入 NPCS。
   运行时不再区分角色用途。 */
const NPCS = {};
for(const id in CHARACTERS) NPCS[id] = CHARACTERS[id];
for(const id in ENVIRONMENTS) NPCS[id] = ENVIRONMENTS[id];

